package com.aadil.ecommerce.entities;import jakarta.persistence.*;import lombok.Data;import org.hibernate.annotations.CreationTimestamp;import org.hibernate.annotations.UpdateTimestamp;import java.math.BigDecimal;import java.time.LocalDateTime;@Table(name = "ProductTable")@Entity@Datapublic class ProductEntity {    @GeneratedValue(strategy = GenerationType.IDENTITY)    @Id    private Long id;    @Column(nullable = false)    private String productName;    @Column(nullable = false)    private String description;    @Column(nullable = false)    private BigDecimal price;    @Column(nullable = false)    private int stockQuantity;    @Column(nullable = false)    private String category;    @CreationTimestamp    @Column(nullable = false,updatable = false)    private LocalDateTime createdAt;    @UpdateTimestamp    @Column(nullable = false)    private LocalDateTime updatedAt;}